// HasIPGroup applies the HasEdge predicate on the "ip_group" edge.
func HasIPGroup() predicate.CDNRecord {
	return predicate.CDNRecord(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, IPGroupTable, IPGroupColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIPGroupWith applies the HasEdge predicate on the "ip_group" edge with a given conditions (other predicates).
func HasIPGroupWith(preds ...predicate.IpGroup) predicate.CDNRecord {
	return predicate.CDNRecord(func(s *sql.Selector) {
		step := newIPGroupStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

