// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CDNRecord) predicate.CDNRecord {
	return predicate.CDNRecord(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CDNRecord) predicate.CDNRecord {
	return predicate.CDNRecord(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CDNRecord) predicate.CDNRecord {
	return predicate.CDNRecord(sql.NotPredicates(p))
}
